UPDATE companies SET description='Packaging Inc. was founded in 1986 in Charlotte, North Carolina, as a family-owned business. The company opened its doors serving the retail bag market and has remained in the same location for over three decades.

Today, Packaging supplies a range of packaging products, including the FiberFlow and FiberForm lines, across the food and industrial packaging sectors. Beyond product supply, the company provides application engineering to help customers select the right size, material, or alternative solution. Its services include in-person and virtual sales support, sample provision after pricing approval, participation in plant trials to certify performance and optimize processes, and technical machine support backed by a specialist who spent 15 years as head engineer at a film machine manufacturer.

The company serves customers in food packaging and industrial packaging, offering tailored product recommendations and trial support for applications in those markets.

Packaging emphasizes its long-term commitment to innovation, noting that its product line has continually evolved over 36 years. The availability of a dedicated machine specialist with deep OEM experience is presented as a key differentiator for technical support and trial optimization.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Product selection and application engineering", "Sales support (in-person and virtual)", "Sample provision", "Plant trial participation and optimization", "Technical machine support"], "industries": ["Food packaging", "Industrial packaging"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned business with over 35 years in the packaging industry", "Dedicated machine specialist with 15 years as head engineer at a top film machine manufacturer", "Plant trial participation and optimization support", "Sample provision for customer testing after pricing approval", "In-person and virtual sales call assistance"], "facts_used": ["Founded in 1986 -> /about-us", "Family-owned business -> /about-us", "Headquartered in Charlotte, NC -> /about-us", "Originally retail bag business -> /about-us", "Now serves food and industrial packaging spectrum -> /about-us", "Products: FiberFlow and FiberForm -> /", "Services: product selection, sales calls, samples, trial participation, tech machine support -> /services", "Machine specialist with 15 years as head engineer at top film machine manufacturer -> /services"], "company_type": "Distributor / reseller", "makes_products": "unclear", "type_evidence": "Originally selling a majority of products in the retail bag business, Premier Packaging now has smart and innovative products across the food and industrial packaging spectrum.", "founded_year": "1986", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='premier-packaging-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Plastic Molding & Tooling, Inc. was founded in 2009 in Winder, Georgia, just northeast of Atlanta. The company was formed by Scott Dittman and Phillip Sparks, who combined their experience in injection molding to establish a plastic manufacturing business focused on quality and service.

The shop specializes in custom injection molding, tooling, and product development, offering prototyping assistance to help entrepreneurs and inventors move from concept to production. It also runs stocking programs designed to keep molded parts available on demand and emphasizes quick turnaround on orders.

The company serves entrepreneurs, inventors, and other customers across the Southeast seeking a local source for custom-molded plastic components. It works with clients regardless of order volume, providing personalized service from prototype through full-scale manufacturing.

The founders'' stated aspiration was to become the injection molding supplier in the Southeast, differentiating through integrity, excellence, and an American-owned, operated model that prioritizes direct customer relationships.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom injection molding", "Tooling", "Product development", "Prototyping", "Stocking programs"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Quick turnaround on orders", "Stocking programs for on-demand part availability", "American owned and operated", "Personalized service regardless of order volume", "Guidance from prototype or sketch through manufacturing"], "facts_used": ["Founded 2009 -> db", "Founders Scott Dittman and Phillip Sparks -> description", "Location Winder, Georgia -> db and page /", "Custom injection molding, tooling, development -> page / nav and content", "Prototyping assistance for entrepreneurs/inventors -> page /", "Stocking programs and quick turnaround -> page /", "American owned and operated -> page /", "Aspiration to be premier supplier in Southeast -> description"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "custom injection molding company", "founded_year": "2009", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='premier-plastic-molding-tooling-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Prettl Automotive is headquartered in Greenville, South Carolina. The company traces its roots to 1953 when Franz W. Prettl founded the PRETTL Group in Germany. Now in its third generation of family ownership, the business is led by Willi and Johannes Prettl, sons of the second-generation leaders Erhardt and Rolf Prettl.

The group’s automotive division focuses on electronics, metal components, and charging systems. Its portfolio includes energy management systems, mobile connectivity solutions for vehicles, and DC-DC charging technology. The company holds certifications including ISO 9001, ISO 13485, ISO 14001, and IATF 16949, reflecting its quality, medical device, environmental, and automotive standards.

Prettl serves the automotive industry, supplying components for electrification and connectivity. The group’s international footprint allows it to support clients across continents.

The company emphasizes a culture of “Eco-Preneurship,” combining long-term family values with a drive to pioneer future business fields such as sustainability and employee empowerment. This philosophy, rooted in the founder’s motto of “the entrepreneur in the company,” aims to give staff the freedom to act as intrapreneurs.', certifications=ARRAY['ISO9001','ISO13485','ISO14001','IATF16949']::text[], profile='{"capabilities": ["Energy management systems", "Mobile connectivity for automotive", "DC-DC charging systems", "Metal component manufacturing", "Automotive electronics"], "industries": ["Automotive", "Energy management systems", "Mobile connectivity", "DC-DC charging"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned, now in third generation", "Global presence on all continents", "Eco-Preneur culture combining tradition with sustainability focus", "Certified to ISO 9001, ISO 13485, ISO 14001, and IATF 16949"], "facts_used": ["Headquarters: Greenville, South Carolina -> db", "Founded 1953 by Franz W. Prettl -> /", "Family-owned, third generation (Willi and Johannes Prettl) -> /", "Over 10,000 employees worldwide -> /", "Certifications: ISO9001, ISO13485, ISO14001, IATF16949 -> db", "Industries: Energy management systems, mobile connectivity for automotive, DC-DC charging -> db", "Products: PRETTL Metal Components GmbH -> db", "Global presence on all continents -> /", "Eco-Preneur culture -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Gegr\u00fcndet wurde die Firma PRETTL 1953 von Franz W. Prettl", "founded_year": "1953", "employee_count": "More than 10,000 worldwide", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='prettl-automotive' AND approved AND profile IS NULL;
UPDATE companies SET description='Prima Distribution Inc. operates from Omaha, Nebraska, where it was incorporated over two decades ago to address the lack of a high-quality distributor for the theatre and concession industry in the Midwest. The company entered the market with a focus on the unique requirements of concession operators, building a reputation for reliable service and competitive pricing.

As the self-described largest distributor of concession foods and equipment in the Midwest, Prima supplies a range of products from its Omaha facility. The company serves customers across Nebraska, throughout Iowa, portions of South Dakota, and the greater St. Louis region. Its staff consists entirely of food-service professionals who bring an average of more than 25 years of industry experience to each transaction.

The company provides both food products and the equipment needed to prepare and serve them, positioning itself as a single-source partner for concession operators in the region.

The business was founded specifically to fill a gap in the Midwest for a distributor that understood the particular demands of theatre and concession operations. That origin story, combined with a team of long-tenured industry veterans, is cited as the foundation for the company’s service-first approach.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Concession food distribution", "Concession equipment distribution", "Regional delivery and logistics"], "industries": ["Theatre", "Concession", "Food service", "Entertainment venues"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Midwest''s largest distributor of concession foods and equipment", "Staffed exclusively with food service professionals averaging 25+ years experience", "Regional delivery network covering Nebraska, Iowa, South Dakota, and greater St. Louis", "Founded to address the need for a high-quality distributor for theatre and concession industry", "Reputation for excellent service and competitive pricing"], "facts_used": ["Incorporated over two decades ago to meet need for high-quality distributor in Midwest for theatre and concession industry -> /", "Celebrating 26th year in business, 2026 marks 27th year -> /", "Staffed exclusively with food service professionals averaging over 25 years industry experience -> /", "Midwest''s largest distributor of concession foods and equipment -> /about", "Located in Omaha, NE, delivering to Nebraska, Iowa, South Dakota, greater St. Louis region -> /about", "Headquarters: Omaha, Nebraska -> db", "Company type: Distributor / reseller -> db"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Prima Distribution is the Midwest''s largest distributor of concession foods and equipment.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='prima-distribution-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Pristine Surgical operates from Manchester, New Hampshire, as a medical device company founded to simplify endoscopy. The company combines single-use endoscopes with cloud-based software to make minimally invasive visualization more efficient, consistent, and safe. While the founding year and ownership structure are not publicly disclosed, the board includes representatives from Piney Lake Capital Management and former Medtronic executives.

The company''s flagship product, Summit™, is a first-of-its-kind 4K single-use surgical arthroscope delivered through a "Scopes as a Subscription™" model with transparent pricing and automated inventory management. All systems come pre-installed with Pristine Connect®, a cloud-based platform that handles inventory, image and video sharing, and digital training checklists. Pristine Surgical is developing a full portfolio of rigid and flexible endoscopes spanning arthroscopy, laparoscopy, and flexible endoscopy, addressing a market of approximately 125 million procedures worldwide each year.

The company serves hospitals, ambulatory surgery centers, and orthopedic surgeons specializing in sports medicine. Clinical users include Southern California Orthopedic Institute, UCLA, Hospital for Special Surgery in New York, Virtua Health in New Jersey, Doral Surgery Center in Florida, and Stetson Lee Orthopaedics in California. The medical advisory board features prominent orthopedic surgeons such as Mark Getelman, MD, David McAllister, MD, Stephen Snyder, MD, and Riley Williams III, MD.

Pristine Surgical was started to remove inefficiency, variability, and safety issues from the endoscopy suite. Conventional reusable systems require costly maintenance contracts, sterilization services, and repairs, while dirty or damaged scopes disrupt workflow and present safety risks. The single-use platform eliminates cleaning and maintenance, reduces operating room setup and teardown time, and provides a new high-definition image for every procedure.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Single-use endoscope manufacturing", "4K surgical arthroscope production", "Cloud-based software development (Pristine Connect\u00ae)", "Subscription-based medical device distribution", "Automated inventory management", "Surgical image and video capture and sharing", "Digital training and checklist platform", "Rigid endoscope development", "Flexible endoscope development"], "industries": ["Medical device", "Endoscopy", "Arthroscopy", "Laparoscopy", "Flexible endoscopy", "Orthopedics", "Sports medicine", "Ambulatory surgery centers"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["First-of-its-kind 4K single-use surgical arthroscope (Summit\u2122)", "Scopes as a Subscription\u2122 pricing model with transparent, predictable pricing", "Pristine Connect\u00ae cloud-based software with automated inventory management", "Sterile, ready-to-use scopes that reduce staff exposure to contaminated instruments", "Plug-and-play setup eliminating equipment maintenance and cleaning time"], "facts_used": ["Headquarters: Manchester, New Hampshire -> db", "Company description: medical device company simplifying endoscopy -> /about", "Product: Summit\u2122 4K single-use surgical arthroscope -> /", "Business model: Scopes as a Subscription\u2122 with transparent pricing -> /", "Software: Pristine Connect\u00ae cloud platform with automated inventory, image/video sharing, digital training -> /", "Product pipeline: arthroscopy, laparoscopy, flexible endoscopy (125M procedures worldwide) -> /", "Executive team: Rich McKillop (CEO/CRO), Gordon Goodchild (CTO), Jeffrey Abrams MD (CMO), Steve Seger (CCO), Stephen Snyder MD (Ambassador) -> /about", "Board: Scott Booth, Chris Cleary, David Matlin, Mike Lazar (Piney Lake Capital, former Medtronic) -> /about", "Medical advisory board: Mark Getelman MD, David McAllister MD, Stephen Snyder MD, Riley Williams III MD -> /", "Clinical users: Southern California Orthopedic Institute, UCLA, Hospital for Special Surgery, Virtua Health, Doral Surgery Center, Stetson Lee Orthopaedics -> /", "Mission: remove inefficiency, variability, safety issues from endoscopy suite -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Pristine Surgical is a medical device company with a mission to simplify endoscopy.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pristine-surgical' AND approved AND profile IS NULL;
UPDATE companies SET description='Pro Form Metals operates a fabrication shop on Dickerson Road in Reno, Nevada. The family-owned business is led by Keith Goguen and serves Northern Nevada and the Lake Tahoe region.

The shop produces custom architectural metalwork including chimney caps, fireplace surrounds, seamless gutters, kitchen range hoods, railings, gates, flashing, and trim. Work ranges from one-off pieces to production runs, all welded and formed in-house. The company also supplies cut-to-length metal roofing panels and sources flat sheet, coil, and structural steel from Metal Sales, AEP Span, Taylor Metals, Western States Metal Roofing, Pacific Steel, and PDM Steel. No roof installation is offered.

Customers include builders, contractors, and homeowners across Reno, Sparks, Truckee, Carson City, Dayton, Fernley, Incline Village, Lake Tahoe, and Minden-Gardnerville. Projects span residential and commercial construction, with an emphasis on Sierra weather resistance.

The company emphasizes local fabrication—every piece is built in its Reno shop—and materials-only supply for roofing, distinguishing it from full-service installers.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom metal fabrication", "Custom chimney cap fabrication", "Custom fireplace surround fabrication", "Seamless gutter fabrication", "Custom kitchen range hood fabrication", "Interior metalwork and accents", "Metal roofing panel supply (cut-to-length)", "Custom flashing and trim fabrication", "Custom railing and gate fabrication", "Welding", "Forming", "One-off and batch production", "Sheet metal and plate steel fabrication"], "industries": ["Residential construction", "Commercial construction", "Roofing", "Architectural metalwork", "Home building and renovation"], "materials": ["Copper", "Stainless steel", "Galvanized metal", "Hot rolled steel", "Blackened steel", "Zinc", "Flat sheet", "Coil", "Structural steel", "Roofing panels", "Siding", "Trim and accessories"], "equipment": [], "volume": "One-off to production runs", "lead_time": "", "tolerances": "", "built_on": ["All fabrication performed in-house at the Reno shop", "Materials-only roofing panel supply (no installation)", "Family-owned and operated", "Custom pieces built to spec for heavy snow and Sierra conditions", "One-off to production-run capability"], "facts_used": ["Location: Reno, NV (Dickerson Road) -> /", "Family-owned, Keith Goguen leads -> /", "Services: chimney caps, fireplace surrounds, gutters, range hoods, railings, gates, flashing, trim, interior metalwork -> /, /services", "Processes: welding, forming, one-off to production runs -> /, /services", "Suppliers: Metal Sales, AEP Span, Taylor Metals, Western States Metal Roofing, Pacific Steel, PDM Steel -> /, /services", "Materials: copper, stainless steel, galvanized, hot rolled steel, blackened steel, zinc, flat sheet, coil, structural steel -> /, /services", "Service areas: Reno, Sparks, Truckee, Carson City, Dayton, Fernley, Incline Village, Lake Tahoe, Minden-Gardnerville -> /", "Customer types: builders, contractors, homeowners -> /", "No roof installation, materials only -> /, /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom metal fabrication in Reno, NV. Brackets, guards, caps, one-offs, and production runs welded and formed to spec at our Dickerson Road shop.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='pro-form-metals' AND approved AND profile IS NULL;
UPDATE companies SET description='Pro Shaper Sheet Metal LLC operates from Charlton, Massachusetts. Wray now leads the company, which evolved from that family tradition into a dedicated metal-shaping resource.

The shop provides TIG, MIG, and specialty welding on steel, stainless steel, and aluminum, along with full custom fabrication and coachbuilding services. It also runs hands-on classes covering wheeling, planishing, shrinking, stretching, and panel development. In addition, Pro Shaper designs and sells professional-grade shaping tools — including shrinking discs, mallet sets with Delrin heads, lead-shot dollies, and shaping kits — curated for serious fabricators.

Customers range from classic-car restorers and Auburn/Cord/Duesenberg club members to fabricators developing one-off concepts and hobbyists building their skills. The company’s coachbuilding work emphasizes period correctness with modern durability, while its classes and tools serve both professional shops and individual builders.

Pro Shaper positions itself as a bridge between old-world coachbuilding discipline and today’s fabrication demands. The team builds and sources tools that “earn their place on the bench” and teaches users to maximize each pass, guided by the principle that “control, patience, and the right tool — that is how great shapes happen.”', certifications=ARRAY[]::text[], profile='{"capabilities": ["TIG welding", "MIG welding", "Specialty welding", "Custom fabrication", "Coachbuilding", "Metal shaping", "Wheeling", "Planishing", "Shrinking", "Stretching", "Panel development", "Hands-on metal shaping classes", "Tooling design and sales", "Tool curation and support"], "industries": ["Classic car restoration", "Coachbuilding", "Automotive restoration", "Collector car community", "Metal fabrication", "Metal shaping education", "Fabricator training"], "materials": ["Steel", "Stainless steel", "Aluminum"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Bridges old-world coachbuilding discipline with modern fabrication demands", "Builds and sources professional-grade shaping tools backed by daily shop use", "Offers hands-on instruction in wheeling, planishing, shrinking, stretching, and panel development", "Delivers coachbuilt panels with period correctness and modern durability", "Emphasizes \u201ccontrol, patience, and the right tool\u201d as the foundation of great shapes"], "facts_used": ["headquarters: Charlton, Massachusetts -> db", "founder Wray learned craft from grandfather Ted Billings in 1960s restoration business -> /about", "offers TIG, MIG, specialty welding on steel, stainless steel, aluminum -> db (description)", "sells professional-grade shaping tools (shrinking disc, mallet set, dolly, kits) -> /", "provides hands-on classes in wheeling, planishing, shrinking, stretching, panel development -> /", "does coachbuilding, structural metal shaping, bespoke panels with period correctness -> /", "serves classic car restoration, collector car enthusiasts, fabricators, hobbyists -> / and /about", "philosophy: bridges old-world coachbuilding discipline with modern demands -> /", "tagline: Control, patience, and the right tool \u2014 that is how great shapes happen -> /", "materials: steel, stainless steel, aluminum -> db (description)", "capabilities: welding, fabrication, coachbuilding, classes, tooling -> db (capabilities) and pages"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We build and source tools that earn their place on the bench", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pro-shaper-sheet-metal-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Progressive Industrial Electrical, Inc. (P-I-E) was established in 2008 in Salt Lake City, Utah. The company has been locally owned and operated since its inception, founded on the principle that strong customer relationships are built through high-quality services at fair prices, with an emphasis on integrity and transparency.

The firm operates as a full-service industrial electrical contractor and a UL 508A-listed panel shop. Its service portfolio spans high-, medium-, and low-voltage power distribution, including pole setting, overhead line work, switchgear and transformer installation, motor control center (MCC) and variable frequency drive (VFD) installation and commissioning. In-house capabilities extend to electrical design using AutoCAD Electrical, PLC and SCADA system design, programming, and upgrades, HMI programming, instrument installation and calibration, and industrial communications such as fiber and copper Ethernet and network configuration.

P-I-E was founded on the principle that strong customer relationships are formed by offering high-quality services at fair prices, emphasizing integrity and transparency. A stated differentiator is the company''s in-house SCADA and controls capabilities, which it notes sets it apart from other contractors.', certifications=ARRAY['UL 508A','UL Listed']::text[], profile='{"capabilities": ["High-voltage power distribution", "Pole setting", "Overhead line work", "Switchgear installation", "Transformer installation", "Medium-voltage power distribution", "MCC installation and commissioning", "VFD installation and commissioning", "Low-voltage power distribution", "Electrical design", "UL 508A panel fabrication", "PLC/SCADA system design", "PLC programming and support", "HMI programming and support", "AutoCAD Electrical drafting", "Instrument installation", "Instrument calibration", "Indoor and outdoor electrical installations", "Fiber and copper Ethernet installation", "Industrial network media installation", "Network configuration"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["In-house SCADA and controls capabilities", "UL 508A-listed panel shop", "Full-service industrial electrical contracting across high, medium, and low voltage", "Electrical design with AutoCAD Electrical"], "facts_used": ["Founded 2008 -> db", "Locally owned and operated -> db", "Headquarters Salt Lake City, Utah -> db", "UL 508A panel shop -> page /", "In-house SCADA/controls capabilities -> page /", "Services: high/medium/low voltage, switchgear, MCC, VFD, electrical design, PLC/SCADA, instrumentation, communications -> page /", "Address 575 W 3900 S, Unit G, Salt Lake City, Utah 84123 -> page /"], "company_type": "Installer / service company", "makes_products": "yes", "type_evidence": "full service industrial electrical contractor and UL 508A panel shop", "founded_year": "2008", "employee_count": "", "cage_code": "", "min_order"