UPDATE companies SET description='Pronghorn Pump LLC was founded in 1996 in Evansville, Wyoming, by Scott Blakeley, a certified pump installer who serves as the company’s owner. The business began as a statewide service and installation operation focused on solar-powered pumping units for remote locations.

The company designs custom remote water systems tailored to each customer’s unique requirements, specializing in solar pumping units. Its services also include water sampling, well testing, and groundwater monitoring, all supported by statewide installation and ongoing maintenance.

The firm emphasizes that no two systems are alike, building each to the exact demands of the end user.

Blakeley’s operation distinguishes itself through a commitment to quality, availability, service, and value, with the owner’s certification underscoring technical credibility. The company pledges to service every installation with the same pride shown during the initial build, maintaining a “we service what we sell” philosophy.', certifications=ARRAY['Certified Pump Installer']::text[], profile='{"capabilities": ["Remote water system design", "Solar pumping unit installation", "Water sampling", "Well testing", "Groundwater monitoring", "Statewide service and installation"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Statewide service and installation coverage", "Custom-designed remote water systems for each client", "Specialization in solar pumping units", "Water sampling, well testing, and groundwater monitoring", "Owner is a certified pump installer"], "facts_used": ["Founded in 1996 -> db", "Headquarters in Evansville, Wyoming -> db", "Owner Scott Blakeley, Certified Pump Installer -> page \"/\"", "Statewide service and installation company -> page \"/\"", "Specializes in solar pumping units -> page \"/\"", "Designs custom remote water systems -> page \"/\"", "Provides water sampling, well testing, groundwater monitoring -> page \"/\"", "Commitment to quality, availability, service, and value -> page \"/\"", "Services installations with pride, ''we service what we sell'' -> page \"/\""], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Pronghorn Pump LLC is a statewide service and installation company specializing in SOLAR PUMPING UNITS.", "founded_year": "1996", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pronghorn-pump-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Provisur Technologies is headquartered in Mokena, Illinois. The company operates as a global manufacturer of food processing equipment, drawing on decades of food science and sales experience. While a specific founding year is not publicly disclosed, the business has built a portfolio of established brands that serve protein processors worldwide.

The company designs and builds equipment for separation, grinding, forming, slicing, cooking, defrosting, and marinating. Key product lines include Weiler mixer grinders, Formax formers, Beehive separators, and Lutetia defrosting tumblers. Provisur runs two Ingenuity Centers where customers can test applications on full-scale machinery. A global staff of food processing professionals provides parts and service support. The company employs approximately 3,000 people.

Provisur serves the food processing industry, with a focus on meat, poultry, seafood, and prepared foods manufacturers. Its equipment produces items such as burgers, pork patties, chicken nuggets, patties and fries, meatballs, and fish sticks. Customers range from large-scale protein processors to companies developing new formed and sliced products.

